arguments.command:
cd /tmp/sv-640c53eb981d4c64938e9fa3808f1f7b/symbols && \
# Use nm -D to get sorted symbols and find the nearest for each address
# For libmonosgen-2.0.so addresses: 0x222098, 0x222234, 0x19bac0, 0x19bc14
for addr in 0x222098 0x222234 0x19bac0 0x19bc14; do
  result=$(aarch64-linux-gnu-nm -D --defined-only libmonosgen-2.0.so 2>/dev/null | sort | awk -v target="$addr" '
    BEGIN { target_dec = strtonum(target); best_name=""; best_addr=0 }
    { 
      addr_dec = strtonum("0x" $1)
      if (addr_dec <= target_dec && addr_dec > best_addr) {
        best_addr = addr_dec
        best_name = $3
      }
    }
    END { printf "%s+0x%x\n", best_name, target_dec - best_addr }
  ')
  echo "  $addr -> $result"
done

