arguments.command:
cd /tmp/sv-640c53eb981d4c64938e9fa3808f1f7b/symbols && \
# The binary has 1537 dynamic symbols. Let's use objdump to find actual function boundaries
# by looking at the PLT/text sections around our target addresses
# Actually, let's just use the function-level granularity from the sorted dynsym
# and look more carefully

# Get all function symbols sorted by address
aarch64-linux-gnu-nm -D --defined-only libmonosgen-2.0.so 2>/dev/null | grep -i " t\| T" | sort > /dev/null

# Actually dynsym includes all exported symbols. Let's find the closest ones properly
# by looking at both T and other types
aarch64-linux-gnu-nm -D --defined-only --numeric-sort libmonosgen-2.0.so 2>/dev/null | awk '
  /^[0-9a-f]/ { addrs[NR] = strtonum("0x" $1); names[NR] = $3; count = NR }
  END {
    split("0x222098 0x222234 0x19bac0 0x19bc14", targets, " ")
    for (t in targets) {
      target = strtonum(targets[t])
      best_i = 0
      for (i = 1; i <= count; i++) {
        if (addrs[i] <= target) best_i = i
        else break
      }
      if (best_i > 0)
        printf "%s -> %s+0x%x\n", targets[t], names[best_i], target - addrs[best_i]
    }
  }
'

